1	/**
2	 * SFCC-270 (plan step 2.2). Covers this build's own pass criteria for product-item/index.tsx:
3	 * image renders with an alt, name renders uppercase, price renders, and the colour+size string
4	 * renders as one combined text node (not two separate ones).
5	 *
6	 * Mocks the smallest surface a rendered ProductItem calls transitively (testing.md's own
7	 * guidance), rather than standing up the full commerce-hook dependency chain a real render
8	 * would need (CurrencyContext, CommerceApiProvider, useVariant/useVariationParams/
9	 * useSelectedStore via the real useDerivedProduct, react-intl's IntlProvider via useIntl) —
10	 * this test is about ProductItem's OWN render contract, not re-proving those hooks' own
11	 * correctness, which is out of this file's scope. `use-multi-site` is mocked for the same
12	 * parse-failure-under-Vitest reason item-variant/index.test.tsx's own docblock explains.
13	 *
14	 * SFCC-795 (plan step 3.2) extends this file with the `message` prop's own pass criteria: DOM
15	 * order (message between the stepper and the actions) and the `hasError` wiring into
16	 * `ZimmCartItem`'s recipe. The gap VALUE itself (12px vs 16px token) is proven directly against
17	 * the exported recipe in product-item.css.test.ts, not here — this file's own `HideOnMobile`/
18	 * `HideOnDesktop` both render simultaneously under jsdom (see the existing price-node comment
19	 * below), which is the same underlying fact (jsdom does not evaluate CSS `@media` rules the way
20	 * a real browser does) that makes a `getComputedStyle`/`toHaveStyle` assertion on a
21	 * media-query-scoped `gap` value unreliable here — so the wiring is proven instead via a
22	 * call-args spy on `useMultiStyleConfig` (still the REAL Chakra implementation underneath,
23	 * `shared/ui/useMultiStyleConfig` is a bare re-export of it — confirmed by reading that file —
24	 * so nothing about ProductItem's actual rendering changes; only its call args are observed).
25	 *
26	 * SFCC-795 (plan step 3.3) extends this file with the `discountLabel` prop's own pass criteria:
27	 * omitted renders no node, present renders the exact copy positioned beneath the stepper and
28	 * ahead of `message` (DOM order proven the same compareDocumentPosition way as the message-vs-
29	 * actions test above). The was/now promotional-price mechanism this step also covers is NOT
30	 * tested in this file — it isn't ProductItem's own contract, it's item-price.tsx's (via base
31	 * `display-price`) — see item-variant/index.test.tsx's own new coverage for that, including a
32	 * disclosed limitation on which of item-price.tsx's two branches can actually reach it.
33	 */
34	import React from 'react';
35	import { describe, test, expect, vi, beforeEach } from 'vitest';
36	import { render, screen, fireEvent, waitFor } from '@testing-library/react';
37	import { ChakraProvider } from '@chakra-ui/react';
38	import { IntlProvider } from 'react-intl';
39	import { MemoryRouter } from 'react-router-dom';
40	import theme from 'app/theme';
41	import useMultiSite from '@salesforce/retail-react-app/app/hooks/use-multi-site';
42	import { useDerivedProduct } from '@salesforce/retail-react-app/app/hooks';
43	import { useMultiStyleConfig } from '@salesforce/retail-react-app/app/components/shared/ui';
44	import ProductItem from '.';
45	
46	vi.mock('@salesforce/retail-react-app/app/hooks/use-multi-site', () => ({
47	  default: vi.fn(),
48	}));
49	
50	// SFCC-795: wraps the REAL useMultiStyleConfig (a bare re-export of @chakra-ui/react's own hook —
51	// confirmed in node_modules/@salesforce/retail-react-app/.../shared/ui/useMultiStyleConfig) in a
52	// vi.fn so its call args are inspectable, without changing what it actually returns/does. Lets
53	// the `hasError` wiring test below prove the exact props ProductItem passes through, rather than
54	// asserting a media-query-scoped computed style value jsdom does not reliably resolve (see this
55	// file's own docblock).
56	vi.mock('@salesforce/retail-react-app/app/components/shared/ui', async (importOriginal) => {
57	  const actual = await importOriginal<typeof import('@salesforce/retail-react-app/app/components/shared/ui')>();
58	  return {
59	    ...actual,
60	    useMultiStyleConfig: vi.fn(actual.useMultiStyleConfig),
61	  };
62	});
63	
64	// SFCC-271-250 (plan step 3.5): useDerivedProduct is now a controllable vi.fn() (was a static
65	// inline factory returning a fixed quantity) so individual tests can drive ZimmQuantityStepper's
66	// min/max/disabled boundaries at a specific quantity — the same vi.mocked(...) pattern already
67	// used below for useMultiSite/useMultiStyleConfig. Default return value is set in beforeEach.
68	vi.mock('@salesforce/retail-react-app/app/hooks', () => ({
69	  useCurrency: () => ({ currency: 'AUD', setCurrency: vi.fn() }),
70	  useDerivedProduct: vi.fn(),
71	}));
72	
73	vi.mock('@salesforce/retail-react-app/app/hooks/use-current-basket', () => ({
74	  useCurrentBasket: () => ({ data: undefined }),
75	}));
