import React from 'react';
import { describe, test, expect, vi } from 'vitest';
import { render, screen, fireEvent } from '@testing-library/react';
import { IntlProvider } from 'react-intl';
import ProductQuantityPicker from './product-quantity-picker';

/**
 * CodeRabbit (SFCC-11 cumulative review): `onItemQuantityChange` was typed `any`, and
 * `handleQuantityChange` unconditionally calls `.then(...)` on its return value — a caller that
 * explicitly supplies a SYNCHRONOUS function (returns a boolean directly, not a Promise) reaches
 * `TypeError: ...then is not a function`, the same crash class `662670f8` already fixed for the
 * *omitted*-prop case. Fixed by widening the type to `boolean | Promise<boolean>` and normalising
 * via `Promise.resolve(...)`.
 *
 * Renders this component directly rather than through the full `ProductItem` tree: its only real
 * dependency is `useIntl()` (an `IntlProvider` ancestor), confirmed by reading both this file and
 * base `quantity-picker/index.jsx` — no ItemVariant/ServerContext/StoreLocatorProvider setup is
 * needed for this specific scenario, unlike `product-item/index.test.tsx`'s own equivalent test
 * for the omitted-prop case.
 *
 * Same ArrowUp-keydown technique as `product-item/index.test.tsx`'s own sibling test — confirmed
 * empirically there that `fireEvent.click`/`fireEvent.mouseDown` on the increment button never
 * reach `handleQuantityChange` in this environment, only a keydown on the actual `<input>` does.
 *
 * Mutation-tested against the pre-fix `.then(...)` call (no `Promise.resolve()` wrapper): the
 * resulting TypeError is thrown asynchronously inside Chakra's own number-input internals, so
 * `not.toThrow()` does not catch it directly — confirmed instead via the overall process exit
 * code (1 with the bug present, 0 with the fix), the same nuance `product-item/index.test.tsx`'s
 * sibling test already documents in full.
 */
const MOCK_PRODUCT = { name: 'Lilac Sand Silk Midi Dress', quantity: 1 };

const renderPicker = (onItemQuantityChange: (quantity: number) => boolean | Promise<boolean>) =>
  render(
    <IntlProvider locale="en-AU" defaultLocale="en-AU">
      <ProductQuantityPicker
        product={MOCK_PRODUCT}
        onItemQuantityChange={onItemQuantityChange}
        stepQuantity={1}
        quantity={1}
        setQuantity={vi.fn()}
      />
    </IntlProvider>,
  );

describe('ProductQuantityPicker', () => {
  test('a synchronous (non-Promise) onItemQuantityChange and actually changing quantity does not throw', () => {
    renderPicker(() => true);

    expect(() => {
      fireEvent.keyDown(screen.getByLabelText('Quantity'), { key: 'ArrowUp' });
    }).not.toThrow();
  });

  test('an asynchronous onItemQuantityChange still works (no regression on the already-fixed shape)', () => {
    renderPicker(() => Promise.resolve(true));

    expect(() => {
      fireEvent.keyDown(screen.getByLabelText('Quantity'), { key: 'ArrowUp' });
    }).not.toThrow();
  });
});

